import io, os

BASE = r"D:\Desktop\VibeCoding\godot_project\github_game_off_shift\shift"

def rd(p):
    with io.open(os.path.join(BASE, p.replace("/", os.sep)), encoding="utf-8") as f:
        return f.read()

def wr(p, t):
    with io.open(os.path.join(BASE, p.replace("/", os.sep)), "w", encoding="utf-8", newline="\n") as f:
        f.write(t)

def patch(p, pairs):
    t = rd(p)
    for old, new in pairs:
        n = t.count(old)
        assert n == 1, "命中 %d 次: %r (%s)" % (n, old[:60], p)
        t = t.replace(old, new)
    wr(p, t)
    print("  patched %s (%d 处)" % (p, len(pairs)))

